def accounts_from_the_single_connection(apps, schema_editor):
    """
    The tenant's one connection becomes its default account, and what it
    already sent, received and had approved is tied to it — so the first
    reply after a second number is added still goes out from the number the
    customer has been talking to.
    """
    WhatsAppConfig = apps.get_model("communications", "WhatsAppConfig")
    WhatsAppTemplate = apps.get_model("communications", "WhatsAppTemplate")
    WhatsAppMessage = apps.get_model("communications", "WhatsAppMessage")
    BulkCampaign = apps.get_model("communications", "BulkCampaign")

    account = WhatsAppConfig.objects.order_by("pk").first()
    if account is None:
        return
    creds = account.credentials or {}
    account.is_default = True
    account.label = "Main number"
    account.phone_number_id = str(creds.get("phone_number_id") or "").strip()[:50]
    account.save(update_fields=["is_default", "label", "phone_number_id"])
    WhatsAppTemplate.objects.filter(account__isnull=True).update(account=account)
    WhatsAppMessage.objects.filter(account__isnull=True).update(account=account)
    BulkCampaign.objects.filter(channel="whatsapp", whatsapp_account__isnull=True).update(
        whatsapp_account=account,
    )


